#include "MP4.TRUN.h"

using namespace MP4;
          
TRUN::TRUN( void )
{
    this->_type.append( "TRUN" );
}

std::string TRUN::description( void )
{
    std::ostringstream o;
    
    o << "MP4 Atom:           " << this->_type << "\n";
    
    return o.str();
}

void TRUN::processData( MP4::BinaryStream * stream, size_t length )
{
    uint8_t v = stream->readUnsignedChar();
    uint32_t f = (stream->readUnsignedChar() << 16) + (stream->readUnsignedChar() << 8) + (stream->readUnsignedChar() << 0);

    has_data_offset = f & 0x0001;
    has_first_sample_flags = f & 0x0004;
    has_sample_duration = f & 0x0100;
    has_sample_size = f & 0x0200;
    has_sample_flags = f & 0x0400;
    has_sample_composition_time_offset = f & 0x0800;

    uint32_t sample_count = stream->readBigEndianUnsignedInteger();
    uint32_t data_offset = 0;
    size_t first_sample_flags = 0;

    if (has_data_offset)
    {
        data_offset = stream->readBigEndianUnsignedInteger();
    }

    if (has_first_sample_flags)
    {
        uint32_t first_sample_flags = stream->readBigEndianUnsignedInteger();
    }

    size_t sample_row_size = (has_sample_duration && 4) + (has_sample_size && 4) + (has_sample_flags && 4) + (has_sample_composition_time_offset && 4);

    size_t t_dur = 0;
    for (size_t k = 0; k < sample_count; ++k)
    {
        Sample sample;

        uint32_t sample_flags = -1;
        uint32_t sample_composition_time_offset = -1;

        if (has_sample_duration) {
            sample.duration = stream->readBigEndianUnsignedInteger();
            t_dur += sample.duration;
        }

        if (has_sample_size) {
            sample.size = stream->readBigEndianUnsignedInteger();
        }

        if (has_sample_flags) {
            sample.flags = stream->readBigEndianUnsignedInteger();
        }

        if (has_sample_composition_time_offset) {
            sample.composition_time_offset = stream->readBigEndianUnsignedInteger();
        }
        samples.push_back(sample);
    }
}
